package runtime

import (
	"fmt"
	"net/url"
	"reflect"
	"strconv"
)

type BindQueryParameterOptions struct {
	Type   string
	Format string
}

type ParamLocation string

const ParamLocationPath ParamLocation = "path"

type BindStyledParameterOptions struct {
	ParamLocation ParamLocation
	Explode       bool
	Required      bool
	Type          string
	Format        string
}

// BindQueryParameterWithOptions supports the subset required by this project:
// optional integer and string query parameters generated by oapi-codegen.
func BindQueryParameterWithOptions(_ string, _ bool, required bool, paramName string, query url.Values, dest interface{}, _ BindQueryParameterOptions) error {
	values, ok := query[paramName]
	if !ok || len(values) == 0 || values[0] == "" {
		if required {
			return fmt.Errorf("missing query parameter: %s", paramName)
		}
		return nil
	}

	switch p := dest.(type) {
	case **int:
		v, err := strconv.Atoi(values[0])
		if err != nil {
			return fmt.Errorf("invalid integer for %s: %w", paramName, err)
		}
		*p = &v
		return nil
	case **string:
		v := values[0]
		*p = &v
		return nil
	default:
		return setPointerToStringAlias(dest, values[0])
	}
}

func BindStyledParameterWithOptions(_ string, paramName string, value string, dest interface{}, opts BindStyledParameterOptions) error {
	if value == "" {
		if opts.Required {
			return fmt.Errorf("missing path parameter: %s", paramName)
		}
		return nil
	}
	switch p := dest.(type) {
	case *string:
		*p = value
		return nil
	default:
		return setValueFromStringAlias(dest, value)
	}
}

func setPointerToStringAlias(dest interface{}, value string) error {
	rv := reflect.ValueOf(dest)
	if rv.Kind() != reflect.Ptr || rv.IsNil() || rv.Elem().Kind() != reflect.Ptr {
		return fmt.Errorf("unsupported destination type")
	}
	elemType := rv.Elem().Type().Elem()
	if elemType.Kind() != reflect.String {
		return fmt.Errorf("unsupported destination type")
	}
	valuePtr := reflect.New(elemType)
	valuePtr.Elem().SetString(value)
	rv.Elem().Set(valuePtr)
	return nil
}

func setValueFromStringAlias(dest interface{}, value string) error {
	rv := reflect.ValueOf(dest)
	if rv.Kind() != reflect.Ptr || rv.IsNil() {
		return fmt.Errorf("unsupported destination type")
	}
	elem := rv.Elem()
	if elem.Kind() != reflect.String {
		return fmt.Errorf("unsupported destination type")
	}
	elem.SetString(value)
	return nil
}
